const ordem = ['início'];
Promise.resolve().then(() => ordem.push('microtask'));
setTimeout(() => {
  ordem.push('timer');
  console.log(ordem.join(' > '));
}, 0);

const ordem = [];
async function executar() {
  ordem.push('início');
  await Promise.resolve();
  ordem.push('depois do await');
}
ordem.push('script');
executar();
ordem.push('fim do script');
setTimeout(() => console.log(ordem.join(' > ')), 0);

let marcador = '';
Promise.resolve('ok')
  .finally(() => { marcador = 'finally executado'; })
  .then((valor) => console.log(marcador + ' / valor: ' + valor));

async function carregar() {
  const resposta = await fetch('http://localhost:3000/alunos');
  const dados = resposta.json();
  console.log(dados);
}
carregar();

const eventos = [];
async function carregar() {
  const r1 = await fetch('http://localhost:3000/a');
  eventos.push('a');
  const r2 = await fetch('http://localhost:3000/b');
  eventos.push('b');
  console.log(eventos.join(' > ') + ' / status ' + r2.status);
}
carregar();
eventos.push('script');

const eventos = [];
async function carregar() {
  const respostas = await Promise.all([
    fetch('http://localhost:3000/a'),
    fetch('http://localhost:3000/b'),
  ]);
  eventos.push('promise.all');
  console.log(eventos.join(' > ') + ' / ' + respostas.length);
}
carregar();
eventos.push('script');

async function carregar() {
  try {
    const resposta = await fetch('http://localhost:3000/alunos/99');
    console.log('status ' + resposta.status);
  } catch (erro) {
    console.log('catch');
  }
}
carregar();

